"""Task execution primitives shared by the CLI implementation."""
import os, re, shlex, subprocess, sys


def render(s, values):
    if not isinstance(s, str):
        return s
    def truth(value):
        return bool(value) and str(value).lower() not in ('false', '0', 'no')
    def atom(expr, scope):
        expr=expr.strip()
        if expr.startswith('not '): return not truth(atom(expr[4:],scope))
        m=re.fullmatch(r'(eq|ne|gt|ge|lt|le)\s+(.+?)\s+(.+)',expr)
        if m:
            op,left,right=m.groups(); a=atom(left,scope); b=atom(right,scope)
            try: a,b=float(a),float(b)
            except (ValueError,TypeError): a,b=str(a),str(b)
            return {'eq':a==b,'ne':a!=b,'gt':a>b,'ge':a>=b,'lt':a<b,'le':a<=b}[op]
        if expr.startswith('"') and expr.endswith('"'): return expr[1:-1]
        key=expr.lstrip('.').lstrip('$')
        return scope.get(key,'')
    # Expand index/value loops used in Taskfile command templates.
    pattern=re.compile(r'{{\s*range\s+\$(\w+)\s*,\s*\$(\w+)\s*:=\s*\.([\w.-]+)\s*}}(.*?){{\s*end\s*}}',re.S)
    for _ in range(10):
        match=pattern.search(s)
        if not match: break
        idxvar,valvar,key,body=match.groups(); seq=values.get(key,[])
        if not isinstance(seq,(list,tuple,dict,str)): seq=[]
        items=list(seq.items()) if isinstance(seq,dict) else list(enumerate(seq))
        rendered=[]
        for ix,item in items:
            scope=dict(values); scope[idxvar]=ix; scope[valvar]=item
            rendered.append(render(body,scope))
        s=s[:match.start()]+''.join(rendered)+s[match.end():]
    # Resolve simple conditional blocks (including one level of nesting).
    cond=re.compile(r'{{\s*if\s+(.+?)\s*}}(.*?){{\s*end\s*}}',re.S)
    for _ in range(20):
        match=cond.search(s)
        if not match: break
        expr,body=match.groups(); branches=body.split('{{else}}',1)
        chosen=branches[0] if truth(atom(expr,values)) else (branches[1] if len(branches)>1 else '')
        s=s[:match.start()]+render(chosen,values)+s[match.end():]
    s=s.replace('{{.}}',str(values.get('.', '')))
    def repl(m):
        key=m.group(1).strip()
        if key.startswith('.'): key=key[1:]
        if key.startswith('$'): key=key[1:]
        v=values.get(key, '')
        if isinstance(v, bool): return str(v).lower()
        if isinstance(v, (list,dict)): return str(v)
